    state = 2
    kept_rows = []
    for i, row in enumerate(rows):
        weight = 0
        if isinstance(row, int):
            weight = row
        elif isinstance(row, str) and row.startswith("|") and row.endswith("|"):
            try:
                weight = int(row[1:-1])
            except ValueError:
                weight = 0
        elif isinstance(row, list):
            for item in row:
                if isinstance(item, int):
                    weight += item
                elif isinstance(item, str):
                    weight += len(item)

        if (state + weight + i) % 7 != 1 or i == len(rows) - 1:
            kept_rows.append(row)

        if weight == 0:
            state = 2
        else:
            state = (3 * state + weight) % 7

    if not kept_rows:
        return 0

    final_state = state
    kept_length = len(kept_rows)
    rotation = final_state % kept_length
    rotated_rows = kept_rows[rotation:] + kept_rows[:rotation]

    total_cost = 0
    for row in rotated_rows:
        if isinstance(row, int):
            quantity = row
            cost = 0
            if quantity > 0:
                if quantity <= 17:
                    cost = quantity * 4
                else:
                    cost = 17 * 4 + (quantity - 17) * 3
            cost = min(cost, 81)
            total_cost += cost

    return int(total_cost)

